def weapons(me, enemy, arena):
    cmds = []

    # Try to grab with front clamp when close and roughly in front
    dist = distance_to(enemy.x, enemy.y)
    bearing = bearing_to(enemy.x, enemy.y)

    clamp = me.weapons.get("front")
    if clamp:
        # If we are already holding, release when enemy is far
        if clamp.get("holding", False):
            if dist > 0.9:
                cmds.append(release("front"))
        else:
            # Attempt grab when within reach and roughly aligned
            if dist <= clamp.get("reach", 0.5) + 0.1 and abs(bearing) < 15:
                cmds.append(grab("front"))

    # Self‑right if we ever get inverted
    if me.inverted:
        cmds.append(self_right())

    return cmds if cmds else None

def norm_angle(a):
    while a > 180:
        a -= 360
    while a < -180:
        a += 360
    return a

