def weapons(me, enemy, arena):
    cmds = []

    # Self‑right if we end up inverted (flipper enables self‑right)
    if me.inverted:
        cmds.append(self_right())
        return cmds

    bearing = bearing_to(enemy.x, enemy.y)
    dist = distance_to(enemy.x, enemy.y)

    # Front flipper: try to flip the enemy when in front and close enough
    flipper = me.weapons.get("front")
    if flipper and flipper.get("type") == "flipper":
        # Use flipper if enemy is roughly ahead and within reach
        if dist <= flipper.get("width", 0.6) + 0.1 and abs(bearing) < 20 and flipper.get("shots_left", 0) > 0:
            cmds.append(flip("front"))

    # Back clamp: try to grab the enemy when they are behind us
    clamp = me.weapons.get("back")
    if clamp and clamp.get("type") == "clamp":
        if clamp.get("holding", False):
            # Release if the enemy has moved far enough away
            if dist > 0.9:
                cmds.append(release("back"))
        else:
            # Grab if the enemy is within reach and behind us
            if dist <= clamp.get("reach", 0.5) + 0.1 and abs(bearing) > 150:
                cmds.append(grab("back"))

    return cmds if cmds else None
